import java.util.*;

public class Main {
    static final int N = 10;
    static String[] grid = new String[N];
    static int[][] scientists = new int[N][N];
    static int[][] rescue = new int[N][N];
    static int[][] infection_time = new int[N][N];
    static int[] delta_i = {-1, 1, 0, 0};
    static int[] delta_j = {0, 0, -1, 1};
    static int[][][][] reach = new int[N][N][N][N];
    static final int MAX_FLOW = 2 * N * N + 2;
    static final int INF = 1000000000;
    static List<Integer>[] adj_list = new ArrayList[MAX_FLOW + 1];
    static int[][] capacity = new int[MAX_FLOW][MAX_FLOW];
    static int[][] flow = new int[MAX_FLOW][MAX_FLOW];
    static int[] ptr = new int[MAX_FLOW];
    static int[] dist = new int[MAX_FLOW];
    static int[] parent = new int[MAX_FLOW];

    static boolean build_level_graph(int s, int t) {
        Arrays.fill(dist, -1);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj_list[u]) {
                if (capacity[u][v] - flow[u][v] > 0 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                }
            }
        }
        return dist[t] != -1;
    }

    static boolean dfs_augment(int u, int t) {
        if (u == t) return true;
        for (int i = ptr[u]; i < adj_list[u].size(); i++) {
            int v = adj_list[u].get(i);
            if (dist[v] == dist[u] + 1 && capacity[u][v] - flow[u][v] > 0 && dfs_augment(v, t)) {
                parent[v] = u;
                return true;
            }
        }
        return false;
    }

    static boolean find_path(int s, int t) {
        Arrays.fill(parent, -1);
        parent[s] = 0;
        return dfs_augment(s, t);
    }

    static void init_network() {
        for (int i = 0; i < capacity.length; i++) {
            Arrays.fill(capacity[i], 0);
            Arrays.fill(flow[i], 0);
        }
    }

    static void add_network_edge(int u, int v, int cap) {
        adj_list[u].add(v);
        adj_list[v].add(u);
        capacity[u][v] += cap;
    }

    static int max_network_flow(int s, int t) {
        int total = 0;
        while (build_level_graph(s, t)) {
            Arrays.fill(ptr, 0);
            while (find_path(s, t)) {
                int push_flow = INF;
                for (int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                    push_flow = Math.min(push_flow, capacity[u][v] - flow[u][v]);
                }
                for (int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                    flow[u][v] += push_flow;
                    flow[v][u] -= push_flow;
                }
                total += push_flow;
            }
        }
        return total;
    }

    static int node_index(int n, int i, int j, boolean right_side) {
        return i * n + j + (right_side ? n * n : 0);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < N; i++) {
            grid[i] = sc.nextLine();
        }
        int n = 0, t = 0;
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine(); // consume remaining line
        int explosion_i = -1, explosion_j = -1;
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch == 'Y') {
                    grid[i] = replaceChar(grid[i], j, 'Y');
                } else if (ch == 'Z') {
                    grid[i] = replaceChar(grid[i], j, 'Z');
                    explosion_i = i;
                    explosion_j = j;
                } else {
                    grid[i] = replaceChar(grid[i], j, '.');
                    scientists[i][j] += ch - '0';
                }
            }
        }
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch != 'Y' && ch != 'Z') {
                    rescue[i][j] += ch - '0';
                }
            }
        }
        for (int i = 0; i < N; i++) {
            Arrays.fill(infection_time[i], -1);
        }
        infection_time[explosion_i][explosion_j] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{explosion_i, explosion_j});
        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int i = cell[0], j = cell[1];
            for (int d = 0; d < 4; d++) {
                int ni = i + delta_i[d], nj = j + delta_j[d];
                if (0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni].charAt(nj) == '.' && infection_time[ni][nj] == -1) {
                    infection_time[ni][nj] = infection_time[i][j] + 1;
                    q.offer(new int[]{ni, nj});
                }
            }
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                Arrays.fill(reach[i][j], null);
                for (int ii = 0; ii < N; ii++) {
                    for (int jj = 0; jj < N; jj++) {
                        reach[i][j][ii][jj] = -1;
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i].charAt(j) == '.') {
                    reach[i][j][i][j] = 0;
                    Queue<int[]> q2 = new LinkedList<>();
                    q2.offer(new int[]{i, j});
                    while (!q2.isEmpty()) {
                        int[] cell = q2.poll();
                        int ii = cell[0], jj = cell[1];
                        if (infection_time[ii][jj] == -1 || reach[i][j][ii][jj] < infection_time[ii][jj]) {
                            for (int d = 0; d < 4; d++) {
                                int ni = ii + delta_i[d], nj = jj + delta_j[d];
                                if (0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni].charAt(nj) == '.') {
                                    if (infection_time[ni][nj] == -1 || reach[i][j][ii][jj] + 1 <= infection_time[ni][nj]) {
                                        if (reach[i][j][ni][nj] == -1) {
                                            reach[i][j][ni][nj] = reach[i][j][ii][jj] + 1;
                                            q2.offer(new int[]{ni, nj});
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        int source = 2 * n * n;
        int sink = 2 * n * n + 1;
        for (int i = 0; i <= MAX_FLOW; i++) {
            adj_list[i] = new ArrayList<>();
        }
        init_network();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (scientists[i][j] > 0) {
                    add_network_edge(source, node_index(n, i, j, false), scientists[i][j]);
                }
                if (rescue[i][j] > 0) {
                    add_network_edge(node_index(n, i, j, true), sink, rescue[i][j]);
                }
                for (int ii = 0; ii < n; ii++) {
                    for (int jj = 0; jj < n; jj++) {
                        if (reach[i][j][ii][jj] != -1 && reach[i][j][ii][jj] <= t) {
                            add_network_edge(node_index(n, i, j, false), node_index(n, ii, jj, true), INF);
                        }
                    }
                }
            }
        }
        System.out.println(max_network_flow(source, sink));
    }

    static String replaceChar(String s, int index, char c) {
        StringBuilder sb = new StringBuilder(s);
        sb.setCharAt(index, c);
        return sb.toString();
    }
}
